// Le a fila de temas pendentes
const fs = require('fs');

const filaPath = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\dados\\fila_temas.json';

let fila = [];
if (fs.existsSync(filaPath)) {
  const raw = fs.readFileSync(filaPath, 'utf-8');
  fila = JSON.parse(raw);
}

// Pega o primeiro tema nao-processado
const tema = fila.find(t => !t.processado);
if (!tema) {
  return [{ json: { error: 'Nenhum tema pendente na fila' } }];
}

// Marca como processado
tema.processado = true;
tema.data_processamento = new Date().toISOString();
fs.writeFileSync(filaPath, JSON.stringify(fila, null, 2), 'utf-8');

return [{ json: tema }];

// Monta o prompt completo para o Gemini
const tema = $input.first().json;

const systemPrompt = `Voce e um roteirista profissional de documentarios de true crime para YouTube brasileiro.
Sua tarefa: criar roteiros detalhados com TOM CORRETO, ESTRUTURA DRAMATICA e INFORMACOES VERIFICAVEIS.

FORMATO DE SAIDA (JSON obrigatorio):
{
  "video_id": "string (formato: tc_AAAAMMDD_nome)",
  "titulo": "TITULO DO VIDEO (max 90 chars, com hook)",
  "tipo": "long_form" | "short",
  "duracao_minutos": number,
  "sinopse": "Resumo em 2 linhas para SEO",
  "segmentos": [
    {
      "indice": number,
      "titulo": "Titulo do bloco",
      "descricao_visual": "Descricao densa de imagem/stock a gerar",
      "tom_narrativo": "descreve o clima emocional",
      "inicio_previsto": "HH:MM:SS",
      "duracao_estimada_seg": number,
      "nome_arquivo": "nome_arquivo_imagem",
      "ponto_visual_importante": "elemento visual marcante a ser gerado"
    }
  ],
  "musica_markers": [{"tempo": "HH:MM:SS", "tipo": "tension|release|climax|ambient"}],
  "tags_seo": ["tag1", "tag2", ...],
  "thumbnail_suggestion": "descricao detalhada para gerador de imagens",
  "notas_producao": "observacoes tecnicas"
}`;

const userPrompt = `TEMA: ${tema.titulo || tema.assunto || tema}
ANGULO: ${tema.angulo || 'Documentario completo de true crime'}
SCORE: ${tema.score || 5}/10

Gere o roteiro completo no JSON especificado.`;

return [{ json: { systemPrompt, userPrompt, tema } }];

// Salva o roteiro JSON no projeto correspondente
const fs = require('fs');
const path = require('path');

// Extrai texto da resposta do Gemini
const inputJson = $input.first().json;
const roteiroTexto = inputJson.candidates?.[0]?.content?.parts?.[0]?.text ||
                     inputJson.error ||
                     JSON.stringify(inputJson);

// Extrai JSON do texto
let roteiro;
try {
  const match = roteiroTexto.match(/```json\n?([\s\S]*?)\n?```/) ||
                roteiroTexto.match(/\{[\s\S]*\}/);
  const jsonStr = match ? match[0].replace(/```json\n?/, '').replace(/\n?```$/, '') : roteiroTexto;
  roteiro = JSON.parse(jsonStr);
} catch(e) {
  return [{ json: { error: 'JSON invalido do Gemini', raw: roteiroTexto.slice(0, 500) } }];
}

const videoId = roteiro.video_id || ('tc_' + new Date().toISOString().slice(0,10).replace(/-/g,''));
roteiro.video_id = videoId;

const projetoDir = path.join('C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\projetos', videoId);
if (!fs.existsSync(projetoDir)) {
  fs.mkdirSync(projetoDir, { recursive: true });
}

// Salva roteiro
const roteiroPath = path.join(projetoDir, `resultado_${videoId}.json`);
fs.writeFileSync(roteiroPath, JSON.stringify(roteiro, null, 2), 'utf-8');

// Atualiza historico
const historicoPath = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\dados\\historico_temas.json';
let historico = [];
if (fs.existsSync(historicoPath)) {
  historico = JSON.parse(fs.readFileSync(historicoPath, 'utf-8'));
}
historico.push({ ...roteiro, data_roteiro: new Date().toISOString() });
fs.writeFileSync(historicoPath, JSON.stringify(historico, null, 2), 'utf-8');

return [{ json: { ...roteiro, caminho_roteiro: roteiroPath } }];
